/* Norte — finanças pessoais. Sem servidor, sem rastreamento; dados locais. */
(() => {
'use strict';
const STORAGE_KEY = 'norte-financas-v1';
const CATEGORIES = ['Alimentação','Transporte','Moradia','Lazer','Estudos','Equipamentos','Saúde','Assinaturas','Impostos e MEI','Viagens','Outros'];
const CATEGORY_COLORS = {'Alimentação':'#74bda3','Transporte':'#314e59','Moradia':'#a1b5d8','Lazer':'#e4bc7d','Estudos':'#9a89cb','Equipamentos':'#d98b78','Saúde':'#77bdd3','Assinaturas':'#87a99b','Impostos e MEI':'#d8a7ad','Viagens':'#77a2ad','Outros':'#aebbb3'};
const ICONS = {
 dashboard:'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
 transactions:'<path d="M7 7h14l-4-4m4 4-4 4M17 17H3l4-4m-4 4 4 4"/>',
 accounts:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 10h20M6 16h3"/>',
 bills:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6"/>',
 sources:'<path d="M12 2v20M17 5.5C15 3 7 3 7 8c0 5 10 2 10 8 0 5-9 5-11 2.5"/>',
 goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 settings:'<path d="M12 3.5 14 3l1 2 2 .7 2.1-1 2 3.4-1.7 1.5v2.7l1.7 1.5-2 3.4-2.1-1-2 .7-1 2h-4l-1-2-2-.7-2.1 1-2-3.4 1.7-1.5V9.6L3.9 8.1l2-3.4 2.1 1 2-.7 1-2z"/><circle cx="12" cy="11.5" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrowUp:'<path d="m7 14 5-5 5 5M12 9v11"/>',
 arrowDown:'<path d="m7 10 5 5 5-5M12 15V4"/>',
 wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M16 15h3"/>',
 chart:'<path d="M4 19V5M4 19h17M8 15l4-5 4 3 4-7"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 alert:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/>',
 edit:'<path d="M4 20h4l11-11a2.5 2.5 0 0 0-4-4L4 16zM13 7l4 4"/>',
 trash:'<path d="M4 7h16M10 11v7M14 11v7M6 7l1 14h10l1-14M9 7V4h6v3"/>',
 close:'<path d="M18 6 6 18M6 6l12 12"/>',
 chevronLeft:'<path d="m15 18-6-6 6-6"/>',
 chevronRight:'<path d="m9 18 6-6-6-6"/>',
 plane:'<path d="M22 2 9.4 14.6M22 2l-7 20-4.6-7.4L3 10z"/>',
 bank:'<path d="m3 9 9-6 9 6M4 9h16M6 9v10M11 9v10M16 9v10M3 21h18M2 19h20"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 upload:'<path d="M12 19V7m-4 4 4-4 4 4M4 7V3h16v4"/>',
 lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 transfer:'<path d="M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4"/>',
 list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
 sparkles:'<path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5zM19 17l.7 2.3L22 20l-2.3.7L19 23l-.7-2.3L16 20l2.3-.7z"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>'
};
const NAV=[['dashboard','Visão geral','dashboard'],['transactions','Movimentações','transactions'],['accounts','Contas e cartões','accounts'],['bills','Contas a pagar','bills'],['sources','Fontes de renda','sources'],['goals','Ir para fora','goals'],['settings','Configurações','settings']];
const ACCOUNT_TYPES={checking:'Conta corrente',savings:'Poupança',investment:'Investimento',cash:'Dinheiro em espécie',credit:'Cartão de crédito'};
const blankState=()=>({version:1,createdAt:new Date().toISOString(),demo:false,accounts:[],sources:[],transactions:[],transfers:[],bills:[],billPayments:[],goals:[],goalContributions:[]});
const ui={page:'dashboard',month:localMonth(),billMonth:localMonth(),selectedGoal:null,txSearch:'',txType:'all',txAccount:'all'};
let store=readStore();let toastTimeout=null;
function svg(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function uid(){return globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function localMonth(d=new Date()){return localDate(d).slice(0,7);}
function addMonth(key,diff){const [y,m]=key.split('-').map(Number);const dt=new Date(y,m-1+diff,1);return localMonth(dt);}
function monthLabel(key,short=false){const [y,m]=key.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{month:short?'short':'long',year:short?undefined:'numeric'}).format(new Date(y,m-1,1)).replace('.','');}
function dateLabel(value){if(!/^\d{4}-\d\d-\d\d$/.test(String(value)))return '—';const [y,m,d]=value.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(y,m-1,d)).replace('.','');}
function money(v,cur='BRL'){const n=Number(v);return new Intl.NumberFormat('pt-BR',{style:'currency',currency:cur,maximumFractionDigits:2}).format(Number.isFinite(n)?n:0);}
function compact(v){const n=Math.abs(Number(v)||0);if(n>=1000000)return (v/1000000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mi';if(n>=1000)return (v/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil';return (v||0).toLocaleString('pt-BR',{maximumFractionDigits:0});}
function value(v){const n=Number(v);return Number.isFinite(n)?n:0;}
function positive(v){return Math.max(0,value(v));}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function fmtPct(p){return `${Math.round(clamp(p,0,100))}%`;}
function getById(table,id){return store[table].find(x=>x.id===id);}
function readStore(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return blankState();const obj=JSON.parse(raw);if(!obj||typeof obj!=='object'||obj.version!==1)throw Error('Formato não suportado');const out=blankState();for(const key of ['accounts','sources','transactions','transfers','bills','billPayments','goals','goalContributions'])out[key]=Array.isArray(obj[key])?obj[key].filter(x=>x&&typeof x==='object'&&typeof x.id==='string').slice(0,20000):[];out.createdAt=obj.createdAt||out.createdAt;out.demo=obj.demo===true;return out;}catch(err){console.warn('Falha ao ler dados:',err);return blankState();}}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));return true;}catch(err){notify('Não foi possível salvar neste navegador. Faça um backup.',true);console.error(err);return false;}}
function commit(message){persist();render();if(message)notify(message);}
function notify(msg,isError=false){const root=document.getElementById('toast-root');root.innerHTML=`<div class="toast ${isError?'error':''}" role="status">${esc(msg)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>root.innerHTML='',3500);}
function accountPosition(id){const a=getById('accounts',id);if(!a)return 0;let total=a.type==='credit'?-positive(a.openingBalance):value(a.openingBalance);for(const t of store.transactions){if(t.accountId===id)total+=(t.type==='income'?1:-1)*value(t.amount);}for(const t of store.transfers){if(t.fromAccountId===id)total-=value(t.amount);if(t.toAccountId===id)total+=value(t.amount);}return total;}
function wealth(){return store.accounts.reduce((sum,a)=>sum+accountPosition(a.id),0);}
function assets(){return store.accounts.filter(a=>a.type!=='credit').reduce((sum,a)=>sum+accountPosition(a.id),0);}
function cardDebt(){return store.accounts.filter(a=>a.type==='credit').reduce((sum,a)=>sum+Math.max(0,-accountPosition(a.id)),0);}
function monthTransactions(month){return store.transactions.filter(t=>t.date?.slice(0,7)===month);}
function monthSummary(month){let income=0,expense=0,recurring=0,variable=0;for(const t of monthTransactions(month)){if(t.type==='income'){income+=value(t.amount);const source=getById('sources',t.sourceId);if(source?.kind==='recurring')recurring+=value(t.amount);else variable+=value(t.amount);}else expense+=value(t.amount);}return {income,expense,saving:income-expense,recurring,variable};}
function monthCategories(month){const map={};for(const tx of monthTransactions(month)){if(tx.type==='expense'){const cat=CATEGORIES.includes(tx.category)?tx.category:'Outros';map[cat]=(map[cat]||0)+value(tx.amount);}}return Object.entries(map).sort((a,b)=>b[1]-a[1]);}
function accountName(id){return getById('accounts',id)?.name||'Conta removida';}
function sourceName(id){return getById('sources',id)?.name||'Receita avulsa';}
function billApplies(b,month){return b.kind==='recurring'?month>=b.startMonth:month===b.startMonth;}
function monthDueDate(month,day){const [y,m]=month.split('-').map(Number);const max=new Date(y,m,0).getDate();return `${month}-${String(Math.min(clamp(value(day),1,31),max)).padStart(2,'0')}`;}
function billStatus(b,month){if(store.billPayments.some(p=>p.billId===b.id&&p.month===month))return 'paid';return monthDueDate(month,b.dueDay)<localDate()?'overdue':'pending';}
function billPayment(b,month){return store.billPayments.find(p=>p.billId===b.id&&p.month===month);}
function goalSaved(goal){return positive(goal.initialSaved)+store.goalContributions.filter(c=>c.goalId===goal.id).reduce((s,c)=>s+positive(c.amount),0);}
function goalTarget(goal){return positive(goal.targetAmount)*(goal.currency==='BRL'?1:positive(goal.rate));}
function remainingInstallments(endDate){if(endDate<localDate())return 0;const today=new Date();const [y,m]=endDate.split('-').map(Number);return Math.max(1,(y-today.getFullYear())*12+(m-1-today.getMonth())+1);}
function goalCalc(g){const target=goalTarget(g),saved=goalSaved(g),remaining=Math.max(0,target-saved),installments=remainingInstallments(g.targetDate),required=installments>0?remaining/installments:remaining;const planned=positive(g.plannedMonthly);const projected=saved+planned*installments;const progress=target>0?saved/target*100:0;const status=saved>=target?'done':installments===0?'past':planned>=required?'ontrack':'needs';return {target,saved,remaining,installments,required,planned,projected,progress,status};}
function chosenGoal(){if(!store.goals.length)return null;let found=getById('goals',ui.selectedGoal);if(!found){found=store.goals[0];ui.selectedGoal=found.id;}return found;}
function safeNumber(input){const n=Number(input);return Number.isFinite(n)&&n>=0?n:NaN;}
function options(list,selected){return list.map(x=>`<option value="${esc(x.value)}" ${x.value===selected?'selected':''}>${esc(x.label)}</option>`).join('');}
function accountOptions(selected,includeCards=true){const list=store.accounts.filter(a=>includeCards||a.type!=='credit').map(a=>({value:a.id,label:`${a.name} · ${ACCOUNT_TYPES[a.type]||'Conta'}`}));return `<option value="">Selecione uma conta</option>`+options(list,selected||list[0]?.value);}
function iconButton(action,id,label,iconName,extra=''){return `<button type="button" class="icon-btn sm" data-action="${action}" data-id="${esc(id)}" aria-label="${esc(label)}" title="${esc(label)}" ${extra}>${svg(iconName)}</button>`;}
function statusBadge(status){const labels={paid:'Pago',pending:'Pendente',overdue:'Atrasado',done:'Concluída',recurring:'Recorrente',variable:'Variável'};return `<span class="badge-status ${esc(status)}">${labels[status]||esc(status)}</span>`;}
function sectionHead(title,subtitle='',right=''){return `<div class="panel-header"><div><h2 class="panel-title">${title}</h2>${subtitle?`<p class="panel-subtitle">${subtitle}</p>`:''}</div>${right}</div>`;}
function heading(title,subtitle,right=''){return `<div class="page-heading"><div><div class="eyebrow">ORGANIZAÇÃO FINANCEIRA</div><h1>${title}</h1><p>${subtitle}</p></div>${right?`<div class="heading-actions">${right}</div>`:''}</div>`;}
function emptyState(iconName,title,message,action='',label=''){return `<div class="empty-state"><div class="empty-state-icon">${svg(iconName)}</div><h3>${title}</h3><p>${message}</p>${action?`<button class="btn btn-primary" data-action="${action}">${svg('plus')}${label}</button>`:''}</div>`;}
function render(){const nav=document.getElementById('side-nav');nav.innerHTML=NAV.map(([page,name,icon])=>`<button class="nav-link ${ui.page===page?'active':''}" data-action="navigate" data-page="${page}" ${ui.page===page?'aria-current="page"':''}>${svg(icon)}<span>${name}</span></button>`).join('');document.getElementById('mobile-bottom-nav').innerHTML=[NAV[0],NAV[1],NAV[2],NAV[5]].map(([page,name,icon])=>`<button class="bottom-link ${ui.page===page?'active':''}" data-action="navigate" data-page="${page}" aria-label="${name}">${svg(icon)}<span>${page==='dashboard'?'Início':page==='transactions'?'Lançamentos':page==='accounts'?'Contas':'Meta'}</span></button>`).join('');document.getElementById('breadcrumb-page').textContent=NAV.find(x=>x[0]===ui.page)?.[1]||'Visão geral';document.getElementById('topbar-today').textContent=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric'}).format(new Date());const views={dashboard:renderDashboard,transactions:renderTransactions,accounts:renderAccounts,bills:renderBills,sources:renderSources,goals:renderGoals,settings:renderSettings};document.getElementById('view').innerHTML=(views[ui.page]||renderDashboard)();}
function navigate(page){ui.page=NAV.some(x=>x[0]===page)?page:'dashboard';closeMenu();closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('drawer-scrim').hidden=true;}
function openMenu(){document.getElementById('sidebar').classList.add('open');document.getElementById('drawer-scrim').hidden=false;}
function currentMonthPicker(){return `<input class="input month-input" type="month" data-filter="month" value="${ui.month}" aria-label="Mês selecionado">`;}
function monthSummaryCards(){const m=monthSummary(ui.month),g=chosenGoal(),goal=g?goalCalc(g):null;const savingHint=!goal?'Crie uma meta para comparar':goal.remaining<=0?'Meta alcançada':goal.installments===0?'Meta: prazo encerrado':`Meta mensal: ${money(goal.required)}`;return `<div class="metric-grid">
  <div class="metric-card featured"><div class="metric-top"><span class="metric-label">Patrimônio líquido</span><span class="metric-icon">${svg('wallet')}</span></div><div><div class="metric-value mono">${money(wealth())}</div><div class="metric-hint">Saldos e investimentos − cartões</div></div></div>
  <div class="metric-card"><div class="metric-top"><span class="metric-label">Entradas do mês</span><span class="metric-icon">${svg('arrowDown')}</span></div><div><div class="metric-value mono text-positive">${money(m.income)}</div><div class="metric-hint">${store.transactions.filter(t=>t.type==='income'&&t.date.slice(0,7)===ui.month).length} receitas registradas</div></div></div>
  <div class="metric-card"><div class="metric-top"><span class="metric-label">Saídas do mês</span><span class="metric-icon">${svg('arrowUp')}</span></div><div><div class="metric-value mono">${money(m.expense)}</div><div class="metric-hint">Gastos realizados e pagos</div></div></div>
  <div class="metric-card"><div class="metric-top"><span class="metric-label">Resultado do mês</span><span class="metric-icon">${svg('chart')}</span></div><div><div class="metric-value mono ${m.saving<0?'text-negative':'text-positive'}">${money(m.saving)}</div><div class="metric-hint">${savingHint}</div></div></div>
</div>`;}
function renderBalanceChart(){const months=Array.from({length:6},(_,i)=>addMonth(ui.month,i-5));const data=months.map(m=>({month:m,...monthSummary(m)}));const hasValues=data.some(d=>d.income>0||d.expense>0);const max=Math.max(1,...data.flatMap(d=>[d.income,d.expense]));const step=max/4;const scales=[4,3,2,1,0].map(i=>`<span>${hasValues?compact(step*i):(i===0?'—':i===4?'0':'')}</span>`).join('');const cols=data.map(d=>`<div class="chart-group"><div class="chart-bars"><div class="chart-bar income" title="Entradas: ${money(d.income)}" style="height:${d.income?Math.max(2,d.income/max*100):0}%"></div><div class="chart-bar expense" title="Saídas: ${money(d.expense)}" style="height:${d.expense?Math.max(2,d.expense/max*100):0}%"></div></div><div class="chart-label">${esc(monthLabel(d.month,true))}</div></div>`).join('');return `<div class="bar-chart" role="img" aria-label="Entradas versus saídas nos últimos seis meses"><div class="chart-scale">${scales}</div><div class="chart-plot"><div class="chart-lines">${'<span></span>'.repeat(5)}</div><div class="chart-columns">${cols}</div></div></div><div class="chart-legend"><span><i class="legend-dot dot-income"></i>Entradas</span><span><i class="legend-dot dot-expense"></i>Saídas</span></div>`;}
function renderDonut(){const cats=monthCategories(ui.month),sum=cats.reduce((s,c)=>s+c[1],0);if(!sum)return `<div class="empty-chart"><div>${svg('chart')}<div>Seus gastos por categoria<br>aparecerão aqui.</div></div></div>`;let angle=0;const seg=cats.map(([cat,v])=>{const next=angle+v/sum*100;const str=`${CATEGORY_COLORS[cat]||'#aebbb3'} ${angle.toFixed(3)}% ${next.toFixed(3)}%`;angle=next;return str;}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${seg})" role="img" aria-label="Distribuição dos gastos por categoria"><div class="donut-center"><strong>${money(sum)}</strong><span>Gasto total</span></div></div><div class="donut-legend">${cats.slice(0,6).map(([cat,v])=>`<div class="donut-legend-row"><span class="flex-center"><i class="color-dot" style="background:${CATEGORY_COLORS[cat]||'#aebbb3'}"></i><span class="ellipsis">${esc(cat)}</span></span><b>${fmtPct(v/sum*100)}</b></div>`).join('')}${cats.length>6?`<div class="muted-small">+ ${cats.length-6} categorias</div>`:''}</div></div>`;}
function renderGoalBanner(){const g=chosenGoal();if(!g)return `<div class="goal-banner"><div class="goal-banner-symbol">${svg('plane')}</div><div style="flex:1"><h3>Seu próximo destino começa com um plano.</h3><p>Defina quanto precisa juntar para estudar ou viajar ao exterior.</p></div><button class="btn btn-primary" data-action="open-goal">Criar meta ${svg('chevronRight')}</button></div>`;const c=goalCalc(g);return `<div class="goal-banner dark"><div class="goal-banner-symbol">${svg('plane')}</div><div style="flex:1;min-width:0"><div class="eyebrow" style="color:#bcdfcf;margin-bottom:2px">META EM DESTAQUE</div><h3>${esc(g.title)}</h3><p>${money(c.saved)} de ${money(c.target)} · até ${dateLabel(g.targetDate)}</p><div class="goal-progress"><span style="width:${clamp(c.progress,0,100)}%"></span></div><div class="progress-note">${fmtPct(c.progress)} da meta alcançada · ${c.remaining?(c.installments?`${money(c.required)} por mês recomendados`:'Prazo encerrado — atualize a meta'):'Meta alcançada!'}</div></div><button class="btn btn-outline-light" data-action="navigate" data-page="goals">Ver plano ${svg('chevronRight')}</button></div>`;}
function latestTx(limit=5){return [...store.transactions].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,limit);}
function txIcon(t){return `<div class="cell-icon ${t.type==='expense'?'expense':''}">${svg(t.type==='income'?'arrowDown':'arrowUp')}</div>`;}
function txRow(t,withActions=true){const cat=t.type==='income'?sourceName(t.sourceId):(t.category||'Outros');const linked=!!store.billPayments.find(p=>p.transactionId===t.id);return `<tr><td><div class="flex-center">${txIcon(t)}<span class="stack"><strong class="ellipsis">${esc(t.description||cat)}</strong><span class="muted-small">${esc(cat)}${linked?' · Conta fixa':''}</span></span></div></td><td>${dateLabel(t.date)}</td><td>${esc(accountName(t.accountId))}</td><td class="text-right"><strong class="mono ${t.type==='income'?'text-positive':'text-negative'}">${t.type==='income'?'+':'−'} ${money(t.amount)}</strong></td>${withActions?`<td><div class="action-buttons">${!linked?iconButton('edit-transaction',t.id,'Editar lançamento','edit'):''}${iconButton('delete-transaction',t.id,'Excluir lançamento','trash')}</div></td>`:''}</tr>`;}
function renderDashboard(){const demoNotice=store.demo?'<div class="setting-warning" style="margin-bottom:16px"><strong>Modo de demonstração</strong>Todos os valores são fictícios. Para começar do zero, vá em Configurações → Apagar tudo.</div>':'';const trans=latestTx(),applied=store.bills.filter(b=>billApplies(b,ui.month)).map(b=>({...b,status:billStatus(b,ui.month)}));const next=applied.filter(b=>b.status!=='paid').sort((a,b)=>a.dueDay-b.dueDay).slice(0,4);return `${heading('Seu dinheiro, com direção.','Acompanhe suas finanças e avance com tranquilidade.',currentMonthPicker())}${demoNotice}${monthSummaryCards()}${renderGoalBanner()}
<div class="section-grid"><section class="panel">${sectionHead('Balanço financeiro','Entradas e saídas nos últimos 6 meses',`<span class="chip">Até ${esc(monthLabel(ui.month))}</span>`)}${renderBalanceChart()}</section><section class="panel">${sectionHead('Para onde foi seu dinheiro?','Distribuição das despesas neste mês')}${renderDonut()}</section></div>
<div class="section-grid equal"><section class="panel">${sectionHead('Movimentações recentes','O que aconteceu com seu dinheiro',`<button class="inline-link" data-action="navigate" data-page="transactions">Ver todas →</button>`)}${trans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Lançamento</th><th>Data</th><th class="text-right">Valor</th></tr></thead><tbody>${trans.map(t=>`<tr><td><div class="flex-center">${txIcon(t)}<span class="stack"><strong class="ellipsis">${esc(t.description|| (t.type==='income'?sourceName(t.sourceId):t.category))}</strong><span class="muted-small">${esc(accountName(t.accountId))}</span></span></div></td><td>${dateLabel(t.date)}</td><td class="text-right"><strong class="mono ${t.type==='income'?'text-positive':'text-negative'}">${t.type==='income'?'+':'−'} ${money(t.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">Nenhuma movimentação ainda.<br>Adicione sua primeira entrada ou saída.</div>'}</section>
<section class="panel">${sectionHead('Contas por acompanhar',`Referência: ${monthLabel(ui.month)}`,`<button class="inline-link" data-action="navigate" data-page="bills">Ver todas →</button>`)}${next.length?`<div class="bill-list">${next.map(b=>`<div class="bill-item"><div class="cell-icon expense">${svg('calendar')}</div><div class="bill-item-main"><span class="bill-item-name">${esc(b.name)}</span><span class="bill-item-description">Vence em ${dateLabel(monthDueDate(ui.month,b.dueDay))}</span></div><div class="text-right"><div class="bill-item-money">${money(b.amount)}</div><div style="margin-top:6px">${statusBadge(b.status)}</div></div></div>`).join('')}</div>`:'<div class="empty-inline">Sem contas pendentes para este mês.<br>Uma ótima notícia!</div>'}</section></div>`;}
function txFiltered(){let rows=[...store.transactions];if(ui.month)rows=rows.filter(t=>t.date?.slice(0,7)===ui.month);if(ui.txType!=='all')rows=rows.filter(t=>t.type===ui.txType);if(ui.txAccount!=='all')rows=rows.filter(t=>t.accountId===ui.txAccount);const q=ui.txSearch.trim().toLowerCase();if(q)rows=rows.filter(t=>[t.description,t.category,accountName(t.accountId),sourceName(t.sourceId),money(t.amount)].some(x=>String(x||'').toLowerCase().includes(q)));return rows.sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||'').localeCompare(a.createdAt||''));}
function renderTxResults(){const tx=txFiltered();return `${tx.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição / categoria</th><th>Data</th><th>Conta</th><th class="text-right">Valor</th><th class="text-right">Ações</th></tr></thead><tbody>${tx.map(t=>txRow(t)).join('')}</tbody></table></div>`:'<div class="empty-inline">Nenhum lançamento corresponde aos filtros selecionados.</div>'}<p class="muted-small" style="margin:14px 0 0">${tx.length} lançamento(s) encontrado(s)</p>`;}
function renderTransactions(){const m=monthSummary(ui.month);return `${heading('Movimentações','Registre cada entrada e saída. Seus saldos são atualizados automaticamente.',`<button class="btn btn-ghost" data-action="export-csv">${svg('download')} Exportar CSV</button><button class="btn btn-primary" data-action="open-transaction">${svg('plus')} Novo lançamento</button>`)}
<div class="stat-strip"><div class="stat-tile"><div class="kicker">Entradas de ${esc(monthLabel(ui.month))}</div><div class="stat-number text-positive">${money(m.income)}</div></div><div class="stat-tile"><div class="kicker">Saídas de ${esc(monthLabel(ui.month))}</div><div class="stat-number text-negative">${money(m.expense)}</div></div><div class="stat-tile"><div class="kicker">Saldo do período</div><div class="stat-number ${m.saving<0?'text-negative':'text-positive'}">${money(m.saving)}</div></div></div>
<section class="panel" style="margin-bottom:18px">${sectionHead('Histórico de lançamentos','Filtre, consulte, edite ou exclua')}
<div class="filter-toolbar"><input class="input toolbar-input" type="search" id="tx-search" data-filter="tx-search" placeholder="Buscar descrição, categoria, conta..." value="${esc(ui.txSearch)}" aria-label="Buscar lançamentos"><input class="input month-input" type="month" data-filter="month" value="${ui.month}" aria-label="Mês do histórico"><select class="select toolbar-select" data-filter="tx-type" aria-label="Tipo de lançamento">${options([{value:'all',label:'Todas'},{value:'income',label:'Entradas'},{value:'expense',label:'Saídas'}],ui.txType)}</select><select class="select toolbar-select" data-filter="tx-account" aria-label="Filtrar por conta">${options([{value:'all',label:'Todas as contas'},...store.accounts.map(a=>({value:a.id,label:a.name}))],ui.txAccount)}</select></div><div id="tx-results">${renderTxResults()}</div></section>
<section class="panel">${sectionHead('Transferências entre contas','Mover dinheiro não é considerado receita nem despesa.',`<button class="btn btn-secondary btn-sm" data-action="open-transfer">${svg('transfer')} Nova transferência</button>`)}${store.transfers.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>De → Para</th><th>Data</th><th>Observação</th><th class="text-right">Valor</th><th></th></tr></thead><tbody>${[...store.transfers].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,15).map(t=>`<tr><td><strong>${esc(accountName(t.fromAccountId))}</strong> → ${esc(accountName(t.toAccountId))}</td><td>${dateLabel(t.date)}</td><td>${esc(t.note||'—')}</td><td class="text-right"><strong>${money(t.amount)}</strong></td><td>${iconButton('delete-transfer',t.id,'Excluir transferência','trash')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">Nenhuma transferência registrada.</div>'}</section>`;}
function cardCycle(card){const today=new Date();const closing=clamp(value(card.closingDay)||25,1,31),due=clamp(value(card.dueDay)||10,1,31);let month=localMonth();if(today.getDate()>closing)month=addMonth(month,1);const end=monthDueDate(month,closing);const [y,m]=month.split('-').map(Number);const startDt=new Date(y,m-1,1);startDt.setDate(1);const prevEnd=monthDueDate(addMonth(month,-1),closing);const prev=[Number(prevEnd.slice(0,4)),Number(prevEnd.slice(5,7)),Number(prevEnd.slice(8,10))];const first=new Date(prev[0],prev[1]-1,prev[2]+1);const start=localDate(first);const dueMonth=due>closing?month:addMonth(month,1);const dueDate=monthDueDate(dueMonth,due);const purchases=store.transactions.filter(t=>t.accountId===card.id&&t.type==='expense'&&t.date>=start&&t.date<=end).reduce((s,t)=>s+value(t.amount),0);return {start,end,dueDate,purchases};}
function renderAccounts(){const summary=`<div class="stat-strip"><div class="stat-tile"><div class="kicker">Ativos (contas e investimentos)</div><div class="stat-number">${money(assets())}</div></div><div class="stat-tile"><div class="kicker">Dívidas em cartões</div><div class="stat-number text-negative">${money(cardDebt())}</div></div><div class="stat-tile"><div class="kicker">Patrimônio líquido</div><div class="stat-number text-positive">${money(wealth())}</div></div></div>`;
const cards=store.accounts.map(a=>{const pos=accountPosition(a.id),credit=a.type==='credit',cycle=credit?cardCycle(a):null;const shown=credit?Math.max(0,-pos):pos;const colors={checking:['#e3f1ed','#257d6a'],savings:['#edf3ff','#547fa9'],investment:['#fff0e1','#a96c38'],cash:['#f0e9fa','#8763ae'],credit:['#42676b','#d8eedd']};const col=colors[a.type]||colors.checking;return `<article class="account-card ${credit?'credit-card':''}"><div class="account-card-head"><div class="account-card-icon" style="background:${col[0]};color:${col[1]}">${svg(credit?'accounts':a.type==='investment'?'chart':'wallet')}</div><div class="stack" style="flex:1"><span class="account-card-name">${esc(a.name)}</span><span class="account-card-type">${ACCOUNT_TYPES[a.type]||'Conta'}</span></div><div class="account-actions">${iconButton('edit-account',a.id,'Editar conta','edit')}${iconButton('delete-account',a.id,'Excluir conta','trash')}</div></div><div class="account-card-amount mono">${money(shown)}</div><div class="account-card-type">${credit?(pos<0?'Dívida total estimada':'Sem dívida pendente'):'Saldo disponível / aplicado'}</div><div class="account-card-footer"><span>${credit?`Vencimento dia ${a.dueDay||10} · fecha dia ${a.closingDay||25}`:'Saldo calculado pelos lançamentos'}</span></div>${credit?`<div class="account-card-footer" style="margin-top:0"><span>Compras no ciclo<br><strong style="color:#fff">${money(cycle.purchases)}</strong></span><span class="text-right">Próx. vencimento estimado<br><strong style="color:#fff">${dateLabel(cycle.dueDate)}</strong></span></div>`:''}</article>`;}).join('');return `${heading('Contas e cartões','Organize bancos, dinheiro, investimentos e o que precisa pagar no crédito.',`<button class="btn btn-ghost" data-action="open-transfer">${svg('transfer')} Transferir</button><button class="btn btn-primary" data-action="open-account">${svg('plus')} Nova conta</button>`)}${summary}${store.accounts.length?`<div class="account-grid">${cards}</div>`:emptyState('bank','Comece cadastrando uma conta','Informe um saldo inicial para acompanhar seu patrimônio e registrar movimentações.','open-account','Cadastrar primeira conta')}
<div class="section-grid equal"><section class="panel">${sectionHead('Como funcionam os saldos','Evite contar o dinheiro duas vezes')}<p class="muted" style="line-height:1.9;font-size:12px;margin:0">O saldo exibido é o <strong>saldo inicial</strong> mais receitas, menos despesas e transferências. Um gasto no cartão aumenta a dívida; pagar o cartão deve ser lançado como <strong>transferência de uma conta para o cartão</strong>.</p></section><section class="panel">${sectionHead('Faturas de cartão','Acompanhamento por ciclo')}${store.accounts.some(a=>a.type==='credit')?`<div class="muted" style="line-height:1.9;font-size:12px">As compras do ciclo são calculadas pelas datas de fechamento cadastradas. O valor devido é o saldo total estimado do cartão, e pode ser diferente da fatura oficial, especialmente com parcelamentos, juros e compras ainda não lançadas.</div>`:'<div class="empty-inline">Cadastre um cartão de crédito para acompanhar compras e datas de vencimento.</div>'}</section></div>`;}
function renderBills(){const bills=store.bills.filter(b=>billApplies(b,ui.billMonth)).sort((a,b)=>a.dueDay-b.dueDay);const statuses=bills.map(b=>({...b,status:billStatus(b,ui.billMonth)}));const total=statuses.reduce((s,b)=>s+positive(b.amount),0);const pending=statuses.filter(b=>b.status!=='paid').reduce((s,b)=>s+positive(b.amount),0);const paid=statuses.filter(b=>b.status==='paid').reduce((s,b)=>s+positive(b.amount),0);return `${heading('Contas a pagar','Acompanhe vencimentos. Ao marcar como paga, a despesa entra nos seus lançamentos.',`<button class="btn btn-primary" data-action="open-bill">${svg('plus')} Nova conta a pagar</button>`)}
<div class="flex-between" style="margin-bottom:17px;flex-wrap:wrap"><div class="heading-actions"><button class="icon-btn" data-action="bill-prev" aria-label="Mês anterior">${svg('chevronLeft')}</button><div class="chip" style="min-width:138px;text-align:center;padding:11px 13px;text-transform:capitalize">${esc(monthLabel(ui.billMonth))}</div><button class="icon-btn" data-action="bill-next" aria-label="Próximo mês">${svg('chevronRight')}</button></div><input class="input month-input" type="month" data-filter="bill-month" value="${ui.billMonth}" aria-label="Mês das contas"></div>
<div class="stat-strip"><div class="stat-tile"><div class="kicker">Total previsto</div><div class="stat-number">${money(total)}</div></div><div class="stat-tile"><div class="kicker">Pago</div><div class="stat-number text-positive">${money(paid)}</div></div><div class="stat-tile"><div class="kicker">A pagar</div><div class="stat-number ${statuses.some(b=>b.status==='overdue')?'text-negative':''}">${money(pending)}</div></div></div>
<section class="panel">${sectionHead(`Contas de ${monthLabel(ui.billMonth)}`,`${statuses.filter(b=>b.status==='paid').length} de ${statuses.length} contas pagas`)}${statuses.length?`<div class="bill-list">${statuses.map(b=>`<div class="bill-item"><div class="cell-icon ${b.status==='paid'?'':'expense'}">${svg(b.status==='paid'?'check':'calendar')}</div><div class="bill-item-main"><span class="bill-item-name">${esc(b.name)}</span><span class="bill-item-description">${esc(b.category)} · vence ${dateLabel(monthDueDate(ui.billMonth,b.dueDay))} · ${b.kind==='recurring'?'Mensal':'Única'}</span></div><div class="bill-item-money">${money(b.amount)}</div>${statusBadge(b.status)}<div class="bill-item-actions">${b.status==='paid'?`<button class="btn btn-ghost btn-sm" data-action="undo-bill" data-id="${esc(b.id)}">Desfazer</button>`:`<button class="btn btn-secondary btn-sm" data-action="pay-bill" data-id="${esc(b.id)}">${svg('check')} Marcar paga</button>`}${iconButton('edit-bill',b.id,'Editar regra da conta','edit')}${iconButton('delete-bill',b.id,'Excluir regra da conta','trash')}</div></div>`).join('')}</div>`:emptyState('calendar','Nenhuma conta prevista','Cadastre contas mensais ou contas de pagamento único.','open-bill','Adicionar conta')}</section>
<p class="muted-small" style="margin:13px 3px">Contas recorrentes aparecem automaticamente nos meses seguintes; os pagamentos são registrados mês a mês. Vencimentos são ajustados para o último dia do mês quando necessário.</p>`;}
function renderSources(){const m=monthSummary(ui.month);const cards=store.sources.map(src=>{const total=store.transactions.filter(t=>t.type==='income'&&t.sourceId===src.id&&t.date.slice(0,7)===ui.month).reduce((s,t)=>s+value(t.amount),0);const n=store.transactions.filter(t=>t.type==='income'&&t.sourceId===src.id&&t.date.slice(0,7)===ui.month).length;return `<article class="source-card"><div class="source-head"><div class="stack"><div class="cell-icon" style="margin-bottom:8px">${svg('sources')}</div><strong style="font-size:15px">${esc(src.name)}</strong><span class="muted-small">${esc(src.note||'Fonte de receita')}</span></div><div class="action-buttons">${iconButton('edit-source',src.id,'Editar fonte','edit')}${iconButton('delete-source',src.id,'Excluir fonte','trash')}</div></div><div>${statusBadge(src.kind||'variable')}</div><div class="source-amount">${money(total)}</div><div class="source-foot"><span>${n} recebimento(s) em ${monthLabel(ui.month,true)}</span><button class="inline-link" data-action="open-transaction" data-type="income" data-source="${esc(src.id)}">Lançar +</button></div></article>`;}).join('');return `${heading('Fontes de renda','Descubra de onde vem seu dinheiro e o que é recorrente ou eventual.',`<button class="btn btn-primary" data-action="open-source">${svg('plus')} Nova fonte</button>`)}
<div class="stat-strip"><div class="stat-tile"><div class="kicker">Total recebido</div><div class="stat-number">${money(m.income)}</div></div><div class="stat-tile"><div class="kicker">Receita recorrente</div><div class="stat-number text-positive">${money(m.recurring)}</div></div><div class="stat-tile"><div class="kicker">Receita variável / avulsa</div><div class="stat-number">${money(m.variable)}</div></div></div>
<div class="filter-toolbar"><input class="input month-input" type="month" data-filter="month" value="${ui.month}" aria-label="Mês das receitas"></div>${store.sources.length?`<div class="source-grid">${cards}</div>`:emptyState('sources','De onde vem o seu dinheiro?','Cadastre cachês, serviços, projetos, bolsas e outras fontes. Depois vincule os recebimentos aos lançamentos.','open-source','Cadastrar fonte')}
<div class="panel"><p class="muted" style="margin:0;line-height:1.8;font-size:12px">A indicação <strong>recorrente</strong> ou <strong>variável</strong> classifica o dinheiro que já entrou. As fontes não geram lançamentos automáticos, evitando contar valores ainda não recebidos.</p></div>`;}
function contributionRows(g){const contribs=store.goalContributions.filter(c=>c.goalId===g.id).sort((a,b)=>b.date.localeCompare(a.date));return contribs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Observação</th><th class="text-right">Aporte</th><th></th></tr></thead><tbody>${contribs.map(c=>`<tr><td>${dateLabel(c.date)}</td><td>${esc(c.note||'Valor reservado')}</td><td class="text-right"><strong class="text-positive">+ ${money(c.amount)}</strong></td><td>${iconButton('delete-contribution',c.id,'Excluir aporte','trash')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">Nenhum aporte registrado. Você pode reservar dinheiro para esta meta.</div>';}
function renderGoals(){const g=chosenGoal();if(!g)return `${heading('Ir para fora','Transforme a vontade de estudar ou viajar no exterior em uma meta concreta.',`<button class="btn btn-primary" data-action="open-goal">${svg('plus')} Nova meta</button>`)}${emptyState('plane','Um destino merece um plano','Defina o valor da viagem, a moeda, a cotação usada e a data-limite. O simulador calculará quanto guardar por mês.','open-goal','Criar minha primeira meta')}`;
const c=goalCalc(g);const status={done:['Meta alcançada!','Você já reservou o valor desejado.','done'],past:['Prazo encerrado','Atualize a data ou reveja o valor da meta.','past'],ontrack:['No caminho certo','Seu aporte mensal planejado é suficiente para alcançar a meta.',''],needs:['Necessita de ajuste',`Para cumprir o prazo, aumente o aporte para ${money(c.required)} por mês.`,'needs']}[c.status];return `${heading('Ir para fora','O planejamento financeiro por trás da sua próxima experiência.',`<button class="btn btn-ghost" data-action="edit-goal" data-id="${esc(g.id)}">${svg('edit')} Editar meta</button><button class="btn btn-primary" data-action="open-goal">${svg('plus')} Nova meta</button>`)}
<div class="filter-toolbar"><select class="select goal-select" data-filter="goal" aria-label="Selecionar meta">${options(store.goals.map(x=>({value:x.id,label:x.title})),g.id)}</select><span class="chip">${store.goals.length} meta(s) cadastrada(s)</span></div>
<div class="goal-layout"><div><div class="goal-hero"><div class="eyebrow">SEU OBJETIVO · ${esc(g.currency)}</div><h2 style="font-size:18px;margin:0 0 7px">${esc(g.title)}</h2><div class="hero-number">${money(g.targetAmount,g.currency)}</div><p>Valor-alvo em ${g.currency}. ${g.currency==='BRL'?'Sem necessidade de conversão.':`Cotação manual: 1 ${g.currency} = ${money(g.rate)}.`}<br>Equivalente estimado: ${money(c.target)}.</p><div class="goal-progress"><span style="width:${clamp(c.progress,0,100)}%"></span></div><div class="goal-hero-bottom"><span>${money(c.saved)} reservados</span><strong>${fmtPct(c.progress)} concluído</strong></div></div>
<section class="panel">${sectionHead('Simulador do seu plano','Recomendação calculada a partir da data atual')}
<div class="goal-insights"><div class="goal-insight"><div class="caption">Falta guardar</div><strong>${money(c.remaining)}</strong><small>Para chegar ao valor-alvo</small></div><div class="goal-insight"><div class="caption">Aporte mensal necessário</div><strong class="text-positive">${c.remaining<=0?money(0):c.installments?money(c.required):'Prazo vencido'}</strong><small>${c.installments} aporte(s) possíveis até o prazo</small></div><div class="goal-insight"><div class="caption">Aporte que você planejou</div><strong>${money(c.planned)}</strong><small>Por mês, em reais</small></div><div class="goal-insight"><div class="caption">Saldo projetado no prazo</div><strong>${money(c.projected)}</strong><small>Se cumprir o valor planejado</small></div></div>
<div class="goal-status ${status[2]}">${svg(c.status==='done'||c.status==='ontrack'?'check':'alert')}<div><strong>${status[0]}</strong><div>${status[1]}</div></div></div><div class="helper-note" style="margin-top:17px">O cálculo considera um aporte neste mês e um em cada mês seguinte até o mês do prazo, inclusive. Os aportes são uma <strong>reserva planejada</strong> e não reduzem automaticamente suas contas bancárias. A cotação é informada por você, não é atualizada em tempo real.</div></section>
<section class="panel" style="margin-top:18px">${sectionHead('Histórico de aportes','Acompanhe valores separados para a meta',`<button class="btn btn-secondary btn-sm" data-action="open-contribution" data-id="${esc(g.id)}">${svg('plus')} Novo aporte</button>`)}${contributionRows(g)}</section></div>
<div><section class="panel" style="margin-bottom:18px">${sectionHead('Resumo da meta','O que você precisa saber')}<div class="bill-list"><div class="bill-item"><div class="cell-icon">${svg('calendar')}</div><div class="bill-item-main"><span class="bill-item-name">Data-limite</span><span class="bill-item-description">Último mês do plano</span></div><strong>${dateLabel(g.targetDate)}</strong></div><div class="bill-item"><div class="cell-icon">${svg('wallet')}</div><div class="bill-item-main"><span class="bill-item-name">Já reservado</span><span class="bill-item-description">Inicial + aportes registrados</span></div><strong>${money(c.saved)}</strong></div><div class="bill-item"><div class="cell-icon">${svg('chart')}</div><div class="bill-item-main"><span class="bill-item-name">Economia do mês</span><span class="bill-item-description">Receitas − despesas realizadas</span></div><strong class="${monthSummary(localMonth()).saving<0?'text-negative':'text-positive'}">${money(monthSummary(localMonth()).saving)}</strong></div></div><div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary" data-action="open-contribution" data-id="${esc(g.id)}">${svg('plus')} Registrar aporte</button><button class="btn btn-ghost" data-action="delete-goal" data-id="${esc(g.id)}">${svg('trash')} Excluir</button></div></section>
<section class="panel">${sectionHead('Suas outras metas','Selecione para ver o planejamento')}${store.goals.map(x=>{const calc=goalCalc(x);return `<button class="goal-mini-item ${x.id===g.id?'active':''}" data-action="choose-goal" data-id="${esc(x.id)}"><div class="cell-icon">${svg('goals')}</div><div style="flex:1;min-width:0;text-align:left"><strong class="ellipsis" style="display:block">${esc(x.title)}</strong><span>${fmtPct(calc.progress)} · ${money(calc.target)}</span><div class="progress-small"><span style="width:${clamp(calc.progress,0,100)}%"></span></div></div></button>`;}).join('')}</section></div></div>`;}
function renderSettings(){const transactions=store.transactions.length;const total=store.accounts.length+store.sources.length+transactions+store.bills.length+store.goals.length;return `${heading('Configurações','Sua organização, suas escolhas e seus dados.')}<div class="setting-panel"><section class="panel" style="margin-bottom:18px">${sectionHead('Privacidade e segurança','Controle total das informações')}<div class="setting-warning"><strong>${svg('lock')} Os dados ficam neste navegador</strong>Este app não envia seus lançamentos para um servidor e não sincroniza automaticamente entre aparelhos. Se você apagar os dados do site ou usar outro celular, precisará importar um backup. Para maior segurança, não cadastre senhas nem números completos de cartão.</div><div class="setting-item"><div><strong>Backup completo</strong><p>Guarde uma cópia JSON com contas, lançamentos, fontes, metas e aportes.</p></div><button class="btn btn-primary" data-action="export-backup">${svg('download')} Baixar backup</button></div><div class="setting-item"><div><strong>Restaurar backup</strong><p>Importe um arquivo JSON gerado pelo Norte. A restauração substituirá todos os dados atuais.</p></div><button class="btn btn-ghost" data-action="import-backup">${svg('upload')} Importar JSON</button></div><input type="file" accept=".json,application/json" id="import-json" style="display:none" aria-label="Arquivo de backup"><div class="setting-item"><div><strong>Baixar lançamentos em CSV</strong><p>Consulte seus registros em planilhas como Excel e Google Sheets.</p></div><button class="btn btn-ghost" data-action="export-csv">${svg('download')} Exportar CSV</button></div></section>
<section class="panel">${sectionHead('Gerenciamento de dados',`${total} registro(s) principais neste dispositivo`)}<div class="setting-item"><div><strong>Preencher com dados de demonstração</strong><p>Teste o aplicativo com valores fictícios. Apaga os dados existentes e os substitui pelo exemplo.</p></div><button class="btn btn-ghost" data-action="load-demo">${svg('sparkles')} Testar exemplo</button></div><div class="setting-item"><div><strong>Apagar meus dados</strong><p>Exclui todas as informações deste dispositivo. Baixe um backup antes se quiser recuperá-las.</p></div><button class="btn btn-danger" data-action="reset-all">${svg('trash')} Apagar tudo</button></div></section><p class="muted-small" style="line-height:1.7;margin:16px 3px">Norte v1.0 · Aplicativo independente, sem login ou conexão bancária. Valores em BRL salvo quando indicado. Não substitui extratos e faturas oficiais.</p></div>`;}
function field(label,name,type='text',val='',extra='',help=''){return `<div class="form-field"><label for="f-${esc(name)}">${label}</label><input class="input" id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(val)}" ${extra}>${help?`<small>${help}</small>`:''}</div>`;}
function selectField(label,name,opts,selected,extra=''){return `<div class="form-field"><label for="f-${esc(name)}">${label}</label><select class="select" id="f-${esc(name)}" name="${esc(name)}" ${extra}>${opts}</select></div>`;}
function modal(title,description,body,action,submit='Salvar'){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(description)}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></div><form id="entity-form" data-form="${esc(action)}"><div class="modal-content">${body}</div><div class="modal-foot"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${esc(submit)}</button></div></form></section></div>`;root.querySelector('input:not([type="hidden"]),select,textarea')?.focus({preventScroll:true});document.body.style.overflow='hidden';}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';}
function openAccount(id){const a=id?getById('accounts',id):null;const body=`<input name="id" type="hidden" value="${esc(a?.id||'')}"><div class="form-grid">${field('Nome da conta','name','text',a?.name||'','required maxlength="70" placeholder="Ex.: Conta principal"')}${selectField('Tipo de conta','type',options(Object.entries(ACCOUNT_TYPES).map(([value,label])=>({value,label})),a?.type||'checking'),'data-field="account-type"')}${field('Saldo inicial / dívida inicial (R$)','openingBalance','number',a?.openingBalance??0,'step="0.01" required placeholder="0,00"','Para cartão, insira o valor da dívida existente, sem sinal negativo.')}<div class="form-field"><label for="f-dueDay">Dia do vencimento do cartão</label><input class="input" id="f-dueDay" name="dueDay" type="number" min="1" max="31" value="${esc(a?.dueDay??10)}"></div><div class="form-field"><label for="f-closingDay">Dia do fechamento do cartão</label><input class="input" id="f-closingDay" name="closingDay" type="number" min="1" max="31" value="${esc(a?.closingDay??25)}"></div></div><div class="modal-note" style="margin-top:17px">Comece com o valor que existe hoje no banco ou com a dívida atual do cartão. Depois disso, registre apenas novas movimentações para não duplicar saldos.</div>`;modal(a?'Editar conta':'Cadastrar conta',a?'Altere os dados do banco ou cartão.':'Bancos, dinheiro, investimentos e cartões.',body,'save-account');updateAccountFields();}
function updateAccountFields(){const form=document.getElementById('entity-form');if(!form||form.dataset.form!=='save-account')return;const credit=form.elements.type.value==='credit';for(const name of ['dueDay','closingDay'])form.elements[name].closest('.form-field').classList.toggle('form-row-hidden',!credit);}
function openSource(id){const s=id?getById('sources',id):null;modal(s?'Editar fonte de renda':'Nova fonte de renda','Organize de onde vem seu dinheiro.',`<input type="hidden" name="id" value="${esc(s?.id||'')}"><div class="form-grid">${field('Nome da fonte','name','text',s?.name||'','required maxlength="80" placeholder="Ex.: Cachês de concertos"')}${selectField('Tipo de renda','kind',options([{value:'variable',label:'Variável / eventual'},{value:'recurring',label:'Recorrente'}],s?.kind||'variable'))}<div class="form-field full"><label for="f-note">Observação (opcional)</label><textarea class="textarea" name="note" id="f-note" rows="3" maxlength="240" placeholder="Ex.: Serviços e apresentações">${esc(s?.note||'')}</textarea></div></div><div class="modal-note" style="margin-top:17px">Cadastrar uma fonte não cria uma entrada. Você poderá vincular os valores quando receber.</div>`,'save-source');}
function openTransaction(id,type='expense',sourceId=''){if(!store.accounts.length){notify('Cadastre uma conta para lançar entradas e saídas.');openAccount();return;}const t=id?getById('transactions',id):null;if(t&&store.billPayments.some(p=>p.transactionId===t.id)){notify('Esta despesa pertence a uma conta fixa. Edite ou desfaça o pagamento na aba Contas a pagar.',true);return;}const kind=t?.type||type;const src=sourceId||t?.sourceId||'';const fields=`<input type="hidden" name="id" value="${esc(t?.id||'')}"><input type="hidden" name="type" value="${kind}">${!t?`<div class="segment form-block" style="margin-top:0"><button type="button" data-action="switch-transaction" data-type="expense" class="${kind==='expense'?'active':''}">Saída / despesa</button><button type="button" data-action="switch-transaction" data-type="income" class="${kind==='income'?'active':''}">Entrada / receita</button></div>`:''}<div class="form-grid">${field('Valor (R$)','amount','number',t?.amount??'','required min="0.01" step="0.01" placeholder="0.00"')}${field('Data','date','date',t?.date||localDate(),`required max="${localDate()}"`)}${selectField('Conta','accountId',accountOptions(t?.accountId||'',kind==='expense'),'required')}${kind==='expense'?selectField('Categoria','category',options(CATEGORIES.map(cat=>({value:cat,label:cat})),t?.category||'Alimentação'),'required'):selectField('Fonte de renda','sourceId',`<option value="">Receita avulsa / sem fonte</option>`+options(store.sources.map(s=>({value:s.id,label:s.name})),src))}<div class="form-field full"><label for="f-description">Descrição</label><input class="input" name="description" id="f-description" value="${esc(t?.description||'')}" maxlength="120" placeholder="Ex.: ${kind==='income'?'Cachê de apresentação':'Almoço'}"></div></div><div class="modal-note" style="margin-top:17px">${kind==='income'?'A entrada aumentará o saldo da conta escolhida.':'A despesa reduzirá o saldo da conta ou aumentará a dívida do cartão.'} Apenas movimentações já realizadas são contabilizadas.</div>`;modal(t?'Editar lançamento':kind==='income'?'Registrar entrada':'Registrar despesa','Registre o movimento com a data em que ocorreu.',fields,'save-transaction',t?'Salvar alterações':'Registrar lançamento');}
function openTransfer(){const froms=store.accounts.filter(a=>a.type!=='credit');if(!froms.length||store.accounts.length<2){notify('É preciso ter pelo menos duas contas, sendo uma delas não cartão.',true);return;}modal('Transferir entre contas','Inclui pagamentos de cartões de crédito.',`<div class="form-grid">${selectField('Conta de origem','fromAccountId',accountOptions(froms[0]?.id,false),'required')}${selectField('Conta de destino','toAccountId',accountOptions(''),'required')}${field('Valor (R$)','amount','number','','required min="0.01" step="0.01" placeholder="0.00"')}${field('Data','date','date',localDate(),`required max="${localDate()}"`)}<div class="form-field full"><label for="f-note">Observação (opcional)</label><input class="input" id="f-note" name="note" maxlength="120" placeholder="Ex.: Pagamento da fatura"></div></div><div class="modal-note" style="margin-top:17px">A transferência não altera o patrimônio total. Ao transferir para um cartão, ela reduz a dívida registrada.</div>`,'save-transfer','Transferir');}
function openBill(id){const b=id?getById('bills',id):null;modal(b?'Editar conta a pagar':'Cadastrar conta a pagar','Recorrente mensal ou vencimento único.',`<input type="hidden" name="id" value="${esc(b?.id||'')}"><div class="form-grid">${field('Descrição da conta','name','text',b?.name||'','required maxlength="80" placeholder="Ex.: Internet, aluguel"')}${field('Valor previsto (R$)','amount','number',b?.amount??'','required min="0.01" step="0.01" placeholder="0.00"')}${selectField('Categoria','category',options(CATEGORIES.map(cat=>({value:cat,label:cat})),b?.category||'Assinaturas'))}${selectField('Repetição','kind',options([{value:'recurring',label:'Todos os meses'},{value:'single',label:'Pagamento único'}],b?.kind||'recurring'))}${field('Dia do vencimento','dueDay','number',b?.dueDay??10,'required min="1" max="31"')}${field('A partir do mês','startMonth','month',b?.startMonth||ui.billMonth,'required','Para conta única, escolha o mês do pagamento.')}<div class="form-field full"><label for="f-note">Observações</label><input class="input" id="f-note" name="note" value="${esc(b?.note||'')}" maxlength="120" placeholder="Opcional"></div></div><div class="modal-note" style="margin-top:17px">A conta só vira despesa quando você a marcar como paga. Atrasos são calculados pelo vencimento e pela data atual.</div>`,'save-bill');}
function payBill(id){const b=getById('bills',id);if(!b||!billApplies(b,ui.billMonth))return;if(billPayment(b,ui.billMonth)){notify('Esta conta já foi paga.');return;}if(!store.accounts.length){notify('Cadastre primeiro uma conta para registrar o pagamento.',true);openAccount();return;}modal('Registrar pagamento',`Referente a ${monthLabel(ui.billMonth)}.`,`<input type="hidden" name="billId" value="${esc(id)}"><input type="hidden" name="month" value="${esc(ui.billMonth)}"><div class="stat-tile" style="margin-bottom:16px"><div class="kicker">${esc(b.name)}</div><div class="stat-number">${money(b.amount)}</div><div class="stat-meta">Vencimento: ${dateLabel(monthDueDate(ui.billMonth,b.dueDay))}</div></div><div class="form-grid">${selectField('Pago com qual conta?','accountId',accountOptions(''),'required')}${field('Data do pagamento','date','date',localDate(),`required max="${localDate()}"`)}</div><div class="modal-note" style="margin-top:17px">Será criada uma despesa de ${money(b.amount)}, vinculada a esta conta. Pagar com cartão de crédito aumenta a dívida do cartão.</div>`,'save-bill-payment','Confirmar pagamento');}
function openGoal(id){const g=id?getById('goals',id):null;modal(g?'Editar meta para o exterior':'Criar meta para o exterior','Planeje a viagem ou o período de estudos com números claros.',`<input type="hidden" name="id" value="${esc(g?.id||'')}"><div class="form-grid">${field('Nome da meta','title','text',g?.title||'','required maxlength="80" placeholder="Ex.: Intercâmbio em Genebra"')}${selectField('Moeda do objetivo','currency',options([{value:'BRL',label:'Real (BRL)'},{value:'CHF',label:'Franco suíço (CHF)'},{value:'EUR',label:'Euro (EUR)'},{value:'USD',label:'Dólar (USD)'}],g?.currency||'CHF'),'data-field="goal-currency"')}${field('Valor-alvo (na moeda escolhida)','targetAmount','number',g?.targetAmount??'','required min="0.01" step="0.01" placeholder="Ex.: 1500"')}${field('Cotação: 1 moeda = quantos reais?','rate','number',g?.rate??'','min="0.0001" step="0.0001" placeholder="Informe a cotação"','Cotação manual; não há câmbio automático.')} ${field('Data-limite','targetDate','date',g?.targetDate||'','required')}${field('Já reservado inicialmente (R$)','initialSaved','number',g?.initialSaved??0,'required min="0" step="0.01"','Dinheiro reservado antes do cadastro.')}<div class="form-field full">${field('Quanto pretende guardar por mês? (R$)','plannedMonthly','number',g?.plannedMonthly??0,'required min="0" step="0.01"','Usado para prever se alcançará o alvo no prazo.')}</div></div><div class="modal-note" style="margin-top:16px">Informe os valores em reais nos campos de reserva e aporte. A taxa de câmbio é uma estimativa que você pode editar a qualquer momento.</div>`,'save-goal');updateGoalCurrency();}
function updateGoalCurrency(){const form=document.getElementById('entity-form');if(!form||form.dataset.form!=='save-goal')return;const brl=form.elements.currency.value==='BRL';const rate=form.elements.rate;rate.closest('.form-field').classList.toggle('form-row-hidden',brl);rate.required=!brl;if(brl)rate.value=1;}
function openContribution(id){const g=getById('goals',id);if(!g)return;modal('Registrar aporte',`Separe uma quantia para ${g.title}.`,`<input type="hidden" name="goalId" value="${esc(id)}"><div class="form-grid">${field('Valor reservado (R$)','amount','number','','required min="0.01" step="0.01"')}${field('Data','date','date',localDate(),`required max="${localDate()}"`)}<div class="form-field full"><label for="f-note">Observação (opcional)</label><input class="input" id="f-note" name="note" maxlength="120" placeholder="Ex.: Parte do cachê que guardei"></div></div><div class="modal-note" style="margin-top:17px">Este registro acompanha seu objetivo, mas não movimenta dinheiro entre contas nem cria despesa. Guarde de fato a quantia no banco ou na reserva escolhida.</div>`,'save-contribution','Adicionar aporte');}
function formErr(message){notify(message,true);return false;}
function requiredMoney(raw,allowZero=false){const n=Number(raw);return Number.isFinite(n)&&(allowZero?n>=0:n>0)&&n<1e13?n:NaN;}
function submitForm(form){const fd=new FormData(form),get=k=>String(fd.get(k)??'').trim(),id=get('id');let amount,entry;switch(form.dataset.form){
case 'save-account': {
 const name=get('name'),type=get('type'),open=Number(get('openingBalance')),due=Number(get('dueDay')),close=Number(get('closingDay'));
 if(!name||!ACCOUNT_TYPES[type]||!Number.isFinite(open)||Math.abs(open)>1e13)return formErr('Confira nome, tipo e saldo da conta.');
 if(type==='credit'&&(open<0||due<1||due>31||close<1||close>31))return formErr('Informe uma dívida positiva e dias de 1 a 31.');
 entry={id:id||uid(),name,type,openingBalance:open,dueDay:due||10,closingDay:close||25};
 if(id){const old=getById('accounts',id);if(!old)return formErr('Conta não encontrada.');if(old.type!==type&&(store.transactions.some(t=>t.accountId===id)||store.transfers.some(t=>t.fromAccountId===id||t.toAccountId===id)))return formErr('Não é possível mudar o tipo de uma conta com movimentações.');Object.assign(old,entry);}else store.accounts.push(entry);
 closeModal();commit(id?'Conta atualizada.':'Conta cadastrada.');break;}
case 'save-source': {
 const name=get('name'),kind=get('kind');if(!name||!['variable','recurring'].includes(kind))return formErr('Preencha a fonte de renda.');entry={id:id||uid(),name,kind,note:get('note')};if(id){const old=getById('sources',id);if(!old)return formErr('Fonte não encontrada.');Object.assign(old,entry);}else store.sources.push(entry);closeModal();commit('Fonte de renda salva.');break;}
case 'save-transaction': {
 const type=get('type'),accountId=get('accountId'),account=getById('accounts',accountId),date=get('date');amount=requiredMoney(get('amount'));if(!Number.isFinite(amount)||!account||!['income','expense'].includes(type)||date>localDate()||!/^\d{4}-\d\d-\d\d$/.test(date))return formErr('Confira valor, data e conta.');if(type==='income'&&account.type==='credit')return formErr('Receitas não podem entrar diretamente no cartão. Use transferência para pagar a fatura.');const sourceId=type==='income'?get('sourceId'):null;if(sourceId&&!getById('sources',sourceId))return formErr('Fonte de renda inválida.');entry={id:id||uid(),type,amount,date,accountId,category:type==='expense'?get('category'):null,sourceId:sourceId||null,description:get('description'),createdAt:getById('transactions',id)?.createdAt||new Date().toISOString()};if(id){const old=getById('transactions',id);if(!old)return formErr('Lançamento não encontrado.');Object.assign(old,entry);}else store.transactions.push(entry);closeModal();commit(id?'Lançamento atualizado.':'Lançamento registrado.');break;}
case 'save-transfer': {
 const fromAccountId=get('fromAccountId'),toAccountId=get('toAccountId'),date=get('date');amount=requiredMoney(get('amount'));if(!Number.isFinite(amount)||!getById('accounts',fromAccountId)||!getById('accounts',toAccountId)||fromAccountId===toAccountId||getById('accounts',fromAccountId).type==='credit'||date>localDate())return formErr('Selecione duas contas diferentes e uma data válida.');if(accountPosition(fromAccountId)<amount)return formErr('Saldo insuficiente na conta de origem.');store.transfers.push({id:uid(),fromAccountId,toAccountId,date,amount,note:get('note'),createdAt:new Date().toISOString()});closeModal();commit('Transferência registrada.');break;}
case 'save-bill': {
 const name=get('name'),kind=get('kind'),startMonth=get('startMonth'),day=Number(get('dueDay'));amount=requiredMoney(get('amount'));if(!name||!Number.isFinite(amount)||!['recurring','single'].includes(kind)||!/^\d{4}-\d\d$/.test(startMonth)||day<1||day>31||!CATEGORIES.includes(get('category')))return formErr('Confira os dados da conta a pagar.');entry={id:id||uid(),name,kind,startMonth,dueDay:day,amount,category:get('category'),note:get('note')};if(id){const old=getById('bills',id);if(!old)return formErr('Conta não encontrada.');Object.assign(old,entry);}else store.bills.push(entry);closeModal();commit('Conta a pagar salva.');break;}
case 'save-bill-payment': {
 const billId=get('billId'),month=get('month'),accountId=get('accountId'),date=get('date');const b=getById('bills',billId);if(!b||!billApplies(b,month)||billPayment(b,month)||!getById('accounts',accountId)||date>localDate())return formErr('Pagamento inválido ou já registrado.');const txId=uid();store.transactions.push({id:txId,type:'expense',amount:value(b.amount),date,accountId,category:b.category,sourceId:null,description:b.name,createdAt:new Date().toISOString()});store.billPayments.push({id:uid(),billId,month,transactionId:txId,accountId,date});closeModal();commit('Pagamento registrado e saldo atualizado.');break;}
case 'save-goal': {
 const title=get('title'),currency=get('currency'),targetDate=get('targetDate'),targetAmount=requiredMoney(get('targetAmount')),rate=currency==='BRL'?1:requiredMoney(get('rate')),initialSaved=requiredMoney(get('initialSaved'),true),plannedMonthly=requiredMoney(get('plannedMonthly'),true);if(!title||!['BRL','CHF','EUR','USD'].includes(currency)||!/^\d{4}-\d\d-\d\d$/.test(targetDate)||![targetAmount,rate,initialSaved,plannedMonthly].every(Number.isFinite))return formErr('Confira valor-alvo, moeda, cotação, data e aportes.');entry={id:id||uid(),title,currency,targetDate,targetAmount,rate,initialSaved,plannedMonthly};if(id){const old=getById('goals',id);if(!old)return formErr('Meta não encontrada.');Object.assign(old,entry);}else store.goals.push(entry);ui.selectedGoal=entry.id;closeModal();commit('Meta salva com sucesso.');break;}
case 'save-contribution': {
 const goalId=get('goalId'),date=get('date');amount=requiredMoney(get('amount'));if(!getById('goals',goalId)||!Number.isFinite(amount)||date>localDate()||!/^\d{4}-\d\d-\d\d$/.test(date))return formErr('Confira a meta, a data e o valor do aporte.');store.goalContributions.push({id:uid(),goalId,date,amount,note:get('note')});closeModal();commit('Aporte adicionado à meta.');break;}
default:formErr('Ação não reconhecida.');}}
function removeEntity(action,id){if(!id)return;switch(action){
 case 'delete-account': {const a=getById('accounts',id);if(!a)return;if(store.transactions.some(t=>t.accountId===id)||store.transfers.some(t=>t.fromAccountId===id||t.toAccountId===id)){notify('Exclua ou mova os lançamentos e transferências ligados a esta conta antes de removê-la.',true);return;}if(confirm(`Excluir a conta "${a.name}"?`)){store.accounts=store.accounts.filter(x=>x.id!==id);commit('Conta excluída.');}break;}
 case 'delete-source': {const s=getById('sources',id);if(s&&confirm(`Excluir "${s.name}"? Receitas antigas permanecerão registradas como avulsas.`)){store.sources=store.sources.filter(x=>x.id!==id);store.transactions.forEach(t=>{if(t.sourceId===id)t.sourceId=null;});commit('Fonte excluída.');}break;}
 case 'delete-transaction': {const t=getById('transactions',id);if(t&&confirm('Excluir este lançamento? O saldo da conta será recalculado.')){store.transactions=store.transactions.filter(x=>x.id!==id);store.billPayments=store.billPayments.filter(p=>p.transactionId!==id);commit('Lançamento excluído.');}break;}
 case 'delete-transfer':if(confirm('Excluir esta transferência? Os dois saldos serão recalculados.')){store.transfers=store.transfers.filter(t=>t.id!==id);commit('Transferência excluída.');}break;
 case 'delete-bill': {const b=getById('bills',id);if(b&&confirm(`Excluir a regra "${b.name}"? Despesas já pagas permanecerão no histórico.`)){store.bills=store.bills.filter(x=>x.id!==id);store.billPayments=store.billPayments.filter(p=>p.billId!==id);commit('Conta a pagar excluída.');}break;}
 case 'undo-bill': {const b=getById('bills',id);const pay=b&&billPayment(b,ui.billMonth);if(pay&&confirm(`Desfazer o pagamento de "${b.name}"? A despesa vinculada será excluída.`)){store.billPayments=store.billPayments.filter(p=>p.id!==pay.id);store.transactions=store.transactions.filter(t=>t.id!==pay.transactionId);commit('Pagamento desfeito.');}break;}
 case 'delete-goal': {const g=getById('goals',id);if(g&&confirm(`Excluir a meta "${g.title}" e todos os aportes dela?`)){store.goals=store.goals.filter(x=>x.id!==id);store.goalContributions=store.goalContributions.filter(c=>c.goalId!==id);ui.selectedGoal=null;commit('Meta excluída.');}break;}
 case 'delete-contribution':if(confirm('Excluir este aporte da meta?')){store.goalContributions=store.goalContributions.filter(c=>c.id!==id);commit('Aporte excluído.');}break;
 }}
function downloadFile(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500);}
function exportBackup(){downloadFile(`norte-backup-${localDate()}.json`,JSON.stringify(store,null,2),'application/json;charset=utf-8');notify('Backup JSON criado. Guarde-o em um local seguro.');}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCsv(){const columns=['Data','Tipo','Descrição','Categoria / fonte','Conta','Valor (BRL)'];const rows=store.transactions.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(t=>[t.date,t.type==='income'?'Entrada':'Saída',t.description,t.type==='income'?sourceName(t.sourceId):t.category,accountName(t.accountId),t.type==='income'?value(t.amount):-value(t.amount)]);const csv='\ufeff'+[columns,...rows].map(row=>row.map(csvCell).join(';')).join('\r\n');downloadFile(`norte-lancamentos-${localDate()}.csv`,csv,'text/csv;charset=utf-8');notify('Lançamentos CSV exportados.');}
function demoData(){const data=blankState();data.demo=true;const a1=uid(),a2=uid(),a3=uid(),s1=uid(),s2=uid(),b1=uid(),b2=uid(),g1=uid();data.accounts=[{id:a1,name:'Conta principal (exemplo)',type:'checking',openingBalance:1700,dueDay:10,closingDay:25},{id:a2,name:'Reserva (exemplo)',type:'savings',openingBalance:800,dueDay:10,closingDay:25},{id:a3,name:'Cartão (exemplo)',type:'credit',openingBalance:180,dueDay:12,closingDay:5}];data.sources=[{id:s1,name:'Projeto mensal',kind:'recurring',note:'Valores fictícios'},{id:s2,name:'Cachês e serviços',kind:'variable',note:'Valores fictícios'}];data.bills=[{id:b1,name:'Internet',kind:'recurring',startMonth:addMonth(localMonth(),-4),dueDay:12,amount:95,category:'Assinaturas',note:''},{id:b2,name:'Transporte mensal',kind:'recurring',startMonth:addMonth(localMonth(),-4),dueDay:20,amount:120,category:'Transporte',note:''}];for(let i=-5;i<=0;i++){const mon=addMonth(localMonth(),i);const mk=(d)=>`${mon}-${String(d).padStart(2,'0')}`;const monthItems=[['income',2200,a1,null,s1,'Receita do projeto',6],['income',550+(i+5)*100,a1,null,s2,'Cachê musical',7],['expense',480+(i+5)*35,a1,'Alimentação',null,'Supermercado e refeições',6],['expense',140,a1,'Transporte',null,'Deslocamentos',7],['expense',110,a3,'Estudos',null,'Material de estudo',7]];for(const [type,amount,accountId,category,sourceId,description,day] of monthItems){data.transactions.push({id:uid(),type,amount,accountId,category,sourceId,description,date:mk(day),createdAt:new Date().toISOString()});}}data.goals=[{id:g1,title:'Intercâmbio (exemplo)',currency:'CHF',targetAmount:1200,rate:7.25,targetDate:`${new Date().getFullYear()+1}-03-22`,initialSaved:1250,plannedMonthly:1500}];data.goalContributions=[{id:uid(),goalId:g1,amount:450,date:localDate(),note:'Aporte de exemplo'}];return data;}
function importBackup(file){if(!file)return;if(file.size>12*1024*1024){notify('O arquivo é muito grande (limite de 12 MB).',true);return;}const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result));if(!parsed||parsed.version!==1||!Array.isArray(parsed.accounts)||!Array.isArray(parsed.transactions)||!Array.isArray(parsed.goals)||!Array.isArray(parsed.bills))throw Error('Formato inválido');if(!confirm('Importar este backup? Todos os dados atuais serão substituídos.'))return;localStorage.setItem(STORAGE_KEY,JSON.stringify(parsed));store=readStore();ui.selectedGoal=null;ui.page='dashboard';render();notify('Backup restaurado com sucesso.');}catch(e){notify('Não foi possível restaurar. Confira o arquivo JSON.',true);console.error(e);}};reader.onerror=()=>notify('Não foi possível ler o arquivo.',true);reader.readAsText(file);}
function handleAction(el,event){const action=el.dataset.action,id=el.dataset.id;
 if(action==='backdrop-close'){if(event.target===el)closeModal();return;}
 if(action==='navigate')return navigate(el.dataset.page);
 if(action==='open-menu')return openMenu();if(action==='close-menu')return closeMenu();if(action==='close-modal')return closeModal();
 if(action==='open-account')return openAccount();if(action==='edit-account')return openAccount(id);
 if(action==='open-source')return openSource();if(action==='edit-source')return openSource(id);
 if(action==='open-transaction')return openTransaction(null,el.dataset.type||'expense',el.dataset.source||'');if(action==='edit-transaction')return openTransaction(id);
 if(action==='switch-transaction')return openTransaction(null,el.dataset.type);
 if(action==='open-transfer')return openTransfer();if(action==='open-bill')return openBill();if(action==='edit-bill')return openBill(id);if(action==='pay-bill')return payBill(id);
 if(action==='open-goal')return openGoal();if(action==='edit-goal')return openGoal(id);if(action==='choose-goal'){ui.selectedGoal=id;return render();}if(action==='open-contribution')return openContribution(id);
 if(action==='bill-prev'){ui.billMonth=addMonth(ui.billMonth,-1);return render();}if(action==='bill-next'){ui.billMonth=addMonth(ui.billMonth,1);return render();}
 if(action.startsWith('delete-')||action==='undo-bill')return removeEntity(action,id);
 if(action==='export-csv')return exportCsv();if(action==='export-backup')return exportBackup();
 if(action==='import-backup')return document.getElementById('import-json')?.click();
 if(action==='load-demo'){if(confirm('Substituir TODOS os dados por um conjunto fictício de exemplo?')){store=demoData();ui.page='dashboard';ui.month=localMonth();ui.billMonth=localMonth();ui.selectedGoal=null;commit('Exemplo carregado. Estes dados são fictícios.');window.scrollTo({top:0,behavior:'instant'});}return;}
 if(action==='reset-all'){if(confirm('Apagar permanentemente todos os dados locais? Esta ação não pode ser desfeita.')&&confirm('Confirma a exclusão de contas, lançamentos e metas?')){store=blankState();ui.selectedGoal=null;ui.page='dashboard';commit('Todos os dados locais foram apagados.');window.scrollTo({top:0,behavior:'instant'});}return;}}
function handleFilter(el){const f=el.dataset.filter;const v=el.value;if(f==='month'){ui.month=v||localMonth();render();}else if(f==='bill-month'){ui.billMonth=v||localMonth();render();}else if(f==='tx-type'){ui.txType=v;document.getElementById('tx-results').innerHTML=renderTxResults();}else if(f==='tx-account'){ui.txAccount=v;document.getElementById('tx-results').innerHTML=renderTxResults();}else if(f==='goal'){ui.selectedGoal=v;render();}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el)handleAction(el,event);});
document.addEventListener('submit',event=>{if(event.target.getAttribute('id')==='entity-form'){event.preventDefault();if(!event.target.reportValidity())return;submitForm(event.target);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='import-json'){importBackup(el.files?.[0]);el.value='';return;}if(el.dataset.filter)handleFilter(el);if(el.dataset.field==='account-type')updateAccountFields();if(el.dataset.field==='goal-currency')updateGoalCurrency();});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.filter==='tx-search'){ui.txSearch=el.value;const target=document.getElementById('tx-results');if(target)target.innerHTML=renderTxResults();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(document.getElementById('modal-root').childElementCount)closeModal();else closeMenu();}});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY){store=readStore();render();notify('Dados atualizados em outra aba.');}});
if('serviceWorker' in navigator&&window.isSecureContext){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Modo offline indisponível:',err)));}
render();
})();
